// Register 217: lowBatteryCapacityPercent
// Register 688: socPercent

const reads = [
    { name: 'lowBatteryCapacity', address: 217, quantity: 1 },
    { name: 'socPercent', address: 688, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name,
    registerAddress: r.address
}));

return [messages];

const flowKey = 'lowsoc_reads';
let collected = flow.get(flowKey) || {};
const expectedCount = 2;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const value = data[0] || 0;

switch(msg.readName) {
    case 'lowBatteryCapacity':
        collected.lowBatteryCapacityPercent = value;
        break;
    case 'socPercent':
        collected.socPercent = value;
        break;
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const lowBatteryCapacityPercent = data.lowBatteryCapacityPercent;
const socPercent = data.socPercent;

if (lowBatteryCapacityPercent === undefined || socPercent === undefined) {
    node.status({ fill: "red", shape: "dot", text: "Missing values" });
    return null;
}

// Get last sent SOC from flow context
let lastSentLowBatterySoc = flow.get("lastSentLowBatterySoc");

// Initialize if first run
if (lastSentLowBatterySoc === null || lastSentLowBatterySoc === undefined) {
    lastSentLowBatterySoc = lowBatteryCapacityPercent;
    flow.set("lastSentLowBatterySoc", lastSentLowBatterySoc);
    node.status({ fill: "blue", shape: "dot", text: "Init: " + lastSentLowBatterySoc });
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";
const now = new Date().toISOString();

let shouldSend = false;
let triggeredAtStep = null;

// Check if SOC is below threshold
if (socPercent < lowBatteryCapacityPercent) {
    // Calculate current step (round down to nearest 5)
    let currentStep = Math.floor(socPercent / 5) * 5;

    // Check if we should send (new step lower than last sent)
    if (currentStep < lastSentLowBatterySoc) {
        shouldSend = true;
        triggeredAtStep = currentStep;
        flow.set("lastSentLowBatterySoc", currentStep);
        node.status({ fill: "yellow", shape: "dot", text: "ALARM: SOC=" + socPercent + " step=" + currentStep });
    } else {
        node.status({ fill: "grey", shape: "ring", text: "Skip: SOC=" + socPercent + " step=" + currentStep + " last=" + lastSentLowBatterySoc });
    }
} else {
    // SOC is above threshold, reset
    if (lastSentLowBatterySoc !== lowBatteryCapacityPercent) {
        flow.set("lastSentLowBatterySoc", lowBatteryCapacityPercent);
        node.status({ fill: "green", shape: "dot", text: "Reset: SOC=" + socPercent + " >= " + lowBatteryCapacityPercent });
    } else {
        node.status({ fill: "green", shape: "ring", text: "OK: SOC=" + socPercent });
    }
}

msg.shouldSend = shouldSend;

if (shouldSend) {
    const state = {
        kind: "InverterAlarmState",
        timestampUtc: now,
        version: 1,
        gatewayId: gatewayId,
        inverterSerialNumber: inverterSN,

        runStateRaw: null,
        commBoardFaultRaw: null,
        warningWord1Raw: null,
        warningWord2Raw: null,
        faultWord1Raw: null,
        faultWord2Raw: null,
        faultWord3Raw: null,
        faultWord4Raw: null,
        workFlagTripData: null,

        activeAlarms: [{
            code: "W11",
            vendorCode: null,
            severity: "WARNING",
            sourceDevice: "inverter",
            category: "battery",
            messageKey: "Battery_LowSOC",
            messageParams: {
                currentSocPercent: socPercent,
                thresholdPercent: lowBatteryCapacityPercent,
                triggeredAtStep: triggeredAtStep
            },
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        }]
    };

    msg.payload = state;
    msg.state = state;
}

return msg;

// Only send if shouldSend is true
if (msg.shouldSend) {
    node.status({ fill: "red", shape: "dot", text: "Sending W11 alarm" });
    return msg;
}

node.status({ fill: "green", shape: "dot", text: "No alarm - skipped" });
return null;
